namespace OpenTPW;

/// <summary>One value or rule that is not taken from original data or hard evidence.</summary>
public sealed record Approximation( string Id, string Area, string Assumption, string EvidenceNeeded );

/// <summary>
/// Register of the compatibility slice's approximations (tagged <c>[APPROX:COMPAT-NNN]</c> at each
/// site, listed in docs/COMPATIBILITY.md "Approximation register"). Logged once at startup so a
/// session log always states what is not original.
/// </summary>
public static class ApproximationRegister
{
	public static readonly IReadOnlyList<Approximation> Compatibility = new Approximation[]
	{
		new( "COMPAT-002", "Sign text", "The LOGFONT width is applied as a horizontal scale that makes the font's average character width (OS/2 xAvgCharWidth) equal lfWidth; the width search and centring are traced (0x100A9F9C). The Mac GDI layer's width rounding is not reproduced.", "captures of long ride names (the Mac GDI layer's width rounding)" ),
		new( "COMPAT-003", "Sign text", "Ride signs apply stored paint RGBA, source-image material strips, effect coefficients and native integer layer blending. Each paint mask is shaped as tp.exe 0x5EBF10 shapes it (offset copy 0x5EA3F0, erosion 0x5EA6D0 or dilation 0x5EA510 by the mask word +4, separable Gaussian 0x5EA8A0 by the parameter +8: Wilde Aap's drop shadow, the gate's shadow, Azteekse Tekens' outline). Each relief is shaded as tp.exe 0x5EB820 does: a shape is built from the glyph coverage (the effect's mask word +0 erodes the binary ink one step at a time, every removed pixel keeping a smoothstep level, 0x5EB270 with 0x5EA1F0; the parameter +8 blurs it with a square Gaussian where the glyphs have coverage, 0x5EB3E0), the normal comes from the shape's next-byte and next-row differences read without clamping (0x5EB8A0), and the colour sum is the strip colour times parameter 2, plus the diffuse and specular terms of parameters 3 to 5, scaled by 255, clamped and truncated. The relief strip resampler is tp.exe 0x5E80D0 (the Mac Bitmap::descimate twin: two bucket averages in 16.16 fixed point; its missing upsampling branch is [EXT:sign-relief-upsample]). The blurs (0x5EA8A0, 0x5EB3E0), the bevel levels (0x5EB270) and the relief arithmetic (0x5EB8A0) run instruction for instruction on emulated x87 registers at the single precision of tp.exe's thread (CRT start-up sets 53 bits, 0x6804D0; DDSCL_FPUSETUP at 0x563914 and 0x563B92 makes the shipped D3DIM.DLL CreateDevice set 24 bits, which the render function 0x576EC0 never changes; the 75 corpus signs differ between 24, 53 and 64 bits, so the precision matters). Open: the glyph coverage. tp.exe draws each line with GDI (the sign's LOGFONT, lfQuality 4 = ANTIALIASED_QUALITY, grayscale smoothing through Uniscribe ScriptStringOut) onto an 8-bit gray DIB twice the mask's size. OpenTPW models those gray levels with the documented Windows 2000/XP grayscale smoothing (`TrueTypeRasterizer`, `CoverageModel.GdiGray4`): 4x4 point samples per pixel, i.e. the 17 levels of GGO_GRAY4 (GetGlyphOutline documents GGO_GRAY2/4/8 as 5/17/65 levels), written as `(level * 255 + 8) / 16`, with no gamma (none is documented for grayscale smoothing; the contrast setting is ClearType only) and no gasp switch (none of the 17 shipped fonts has a `gasp` table). Documented: the level counts, grayscale smoothing as overscale and downsample of a grid-fitted outline, gasp semantics, the absence of a grayscale gamma. Unverified against a GDI capture: that ANTIALIASED_QUALITY uses exactly 4x4 sampling (inferred from GGO_GRAY4; Microsoft states no factor), the sample positions and edge rule, the hinted outline (the fonts carry hinting programs, and OpenTPW has no TrueType bytecode interpreter, so no hinting is applied), the dropout control the fonts request (prep SCANCTRL 0x1FF, SCANTYPE 1; not applied), the level to byte mapping on the 8-bit DIB (its palette and GDI's colour matching), and the Windows version the game ran on", "a captured original sign texture (the text DIB or the composed halves), or the GDI rasterizer of the Windows version the game ran on" ),
		new( "COMPAT-004", "Sign text", "The gate is composed from its decoded board with the park name as two lines (as the original draws them) and the stored paint (a 60 % black shadow under dark relief stone text, as in the video); gate pixels (board placement, relief strength) are compared with a 720p capture only.", "original-platform gate capture at the native resolution" ),
		new( "COMPAT-007", "Sign text", "The park name is the gate's two sign lines: they start as the gate's OBJECT_NAMES row (0x4DB6F9), the entry price window's rename dialog (0x4990F0, OK 0x4993E0) stores them and redraws the gate, and OpenTPW's world save keeps them. Its secret name (\"Kevin the\" / \"Cosmic Cow\", compared with 0x751A34/0x751A38) turns the cheat mode on (0x4053C0(1), the CHTS byte, the twelve Alt keys of the cheat key context 0x78733C; built, docs/CHEATS.md). The OK handler's other effects are not built: the copies to the online park record (0x409410, 0x5B0940/0x5B0970, +0x34/+0x76 of the 0x50-byte record DAT_00F7C58C, unless GameType is 1) and the message of type 0x15 that 0x4053C0 posts (0x40FB10). Gate lines of a user-supplied original save are not imported (the attraction record carries them; the shipped Easymode save holds the default row).", "what the listeners of message type 0x15 do (runtime subscriptions of the message centre 0x788D3C)" ),
		new( "COMPAT-018", "Sign text", "The native wavelet container and board alpha blit are implemented for ride signs. tp.exe compares the BILZ chunk tag at 0x6193D0 (the inflate step); everything after it is read and ported instruction for instruction at the x87 precision of the main thread (24 bits after the Direct3D device is created, which precedes the wavelet codec's registration at 0x564B20 and every sign board decode): the header scale multiplies each dequantised coefficient (0x592B80, and inlined in 0x592E60), the D4 coefficients are the 53 bit static initialisers 0x591600..0x591690 stored as float32, the row inverse 0x592C50 (short, steady, last-pair and wrap forms) and the column passes 0x5933A0 (colour) and 0x592E60 (alpha) add in the original's operand order, the colour conversion 0x5935A0 forms the chroma terms once per 2x2 block and rounds each sum through the 1.5 x 2^23 magic number into the 512-entry clamp table, and the alpha conversion is the clamp and truncation at 0x593301; the header floats feed the planes in the order Y, Cb, Cr, alpha: the PC board reader 0x5E7990 (called by the sign reader 0x5EC3A0) passes the four floats in file order to the codec's 0x592000 (vtable 0x7026B8 slot 3 through the thunk 0x5987B0, which runs the colour decode 0x592730 or the alpha decode 0x592E60 by a flag argument), once for colour with the first three as the Y, Cb and Cr scales (0x5935A0 reads plane 1 as luma and planes 2 and 3 as the 1.772 and 1.402 chroma) and once for alpha with the fourth; a constant opaque alpha plane decodes to 254 on even and 255 on odd rows, which is the float32 rounding of the original's D4 taps (their sums differ in the last bit and 0x593301 truncates), not an orientation fault; still open: the GPU row orientation of the uploaded texture, a machine whose Direct3D driver lacks DrawPrimitives2 (53 bits) and original-platform board pixels", "the GPU row orientation, independent native bitmap pixels and an original ride-sign capture" ),
				new( "COMPAT-032", "Sign text", "In the original a textured face's state word follows its texture's alpha type (0x581790 -> 0x590C40, texture flags +8 & 0x300: 0x100 alpha blend with an alpha test at 0xF0/255 (0x2756), 0x200 alpha blend with an alpha test at 0x10/255 (0x556), 0x300 source-alpha-over-one (0x200552), else opaque (0x1256)), all with depth writes (decoder 0x567620), and the batcher 0x581DB0 orders by state and texture; OpenTPW draws the faces with its own alpha test and blend (an extension). The sign textures are the placeholders sign1.wct and sign2.wct of lobby.wad (128x128, 24 bits per pixel, alpha byte 0, no alpha plane: type 0x24, which alone would give the opaque 0x1256); the sign builder (the slot scan 0x467CB3 and 0x467D18, the 128x128 image records and composition 0x4680C1-0x468147) replaces their image records, sets slot flags 0x2|0x8 (A) and 0x2|0x10 (B), ORs 0x480 into the face word and 0x8000000 into the mesh flags (point MAGFILTER, 0x5817D8), the image records it hands to the slots (0x2c bytes, zero except the 128x128 size at +6 and +8, flag 0x2 and the pixel pointers from 0x57B120; the composition copies 32-bit rows into them, 0x5ECF2C) carry no header alpha byte or bits per pixel, and no write of an alpha-type bit was found in it or in the loaders it uses; the only writers of those bits are the texture file loader 0x5755F0/0x574BD0 (header type, load flag 8 -> 0x300), the kids-heads and handymen sprite sets 0x5882E0 (0x200) and the sprite loaders 0x588820 and 0x588410. So whether the generated sign face is drawn opaque (0x1256, ignoring the composed ARGB's alpha, against the video, where wood and sky show between the letters) or with an alpha type the slot binder gives it is not settled.", "how the composed sign image's alpha reaches the draw: the slot binder and texture creation for an image record of the sign slots (0x575870, 0x590EB0) and the meaning of the slot flag 0x8 in the sign builder" ),
		new( "COMPAT-033", "Sign text", "A Hangul sign (the Korean CD's gulim.ttc) is laid out as Latin is, which the shipped usp10.dll does for Hangul too (the itemizer 0x65112330 gives U+AC00..U+D7A3 script 12, whose row of the routine table 0x65108E74 holds the generic shaper 0x6511325C and placer 0x65113458: one glyph per UTF-16 unit by the font's cmap, summed per-glyph advances, no jamo composition or kerning; tp.exe passes UTF-16 and flag 0x80 only, no SSA_FALLBACK, 0x5EACE0). usp10 takes each advance from GDI as an integer pixel width at the LOGFONT size (GetGlyphOutlineA with GGO_METRICS, gmCellIncX, 0x6510EB3E) and GDI draws Gulim with its TrueType instructions; OpenTPW scales the hmtx advance without rounding and rasterizes the unhinted outline, so Hangul advances and coverage differ by the sub-pixel rounding and hinting (the Latin fonts' COMPAT-002 and COMPAT-003 gap, larger for a hinted East Asian font).", "a capture of an original Korean sign (the integer advances and gray levels of Gulim at the sign's em height)" ),
		new( "COMPAT-034", "Sign text", "A sign whose text holds Hebrew (the gate's park name, OBJECT_NAMES, in the Hebrew language) is laid out in logical order. None of the 17 TrueType fonts of fonts.wad has a Hebrew glyph, so each letter is the font's .notdef box in both games, but tp.exe's sign function hands the UTF-16 line to usp10's ScriptStringAnalyse (dwFlags 0x80, 0x5EACE0), which runs the bidirectional algorithm on its strong right-to-left letters, and ScriptStringOut draws visual order: the words of a Hebrew name trade places there (only their lengths show, as rows of boxes). Whether usp10's Hebrew shaping engine draws boxes at all for a font without the script (no SSA_FALLBACK) is not read; the BF4 interface text's own right-to-left pass (TextVisualOrder, 0x6ae4b0) does not apply to signs. The localisation pack carries no fonts.wad (the Korean CD shows that a CD can ship its own sign fonts), so whether the Hebrew release had Hebrew sign fonts is unknown.", "a capture of an original Hebrew gate sign (boxes in visual order, Hebrew letters, or nothing), or the Hebrew CD's fonts.wad" ),
				new( "COMPAT-010", "Graphics presets", "tp.exe's state decoder 0x567620 sets stage 0 from each primitive's state word: 0x20000 -> MAGFILTER point (else linear), 0x40000 -> MIPFILTER none (else the device's mode 1-3 chosen at 0x566840 from DAT_008BD550 bits 0x2, 0x8 and 0x10 and the device's caps), 0x400000 -> wrap addressing with a linear MINFILTER (else clamp with a point MINFILTER). The state bits come from the face, not from an option: bit 0x20000 from bit 0x8000000 of the part's mesh flag word (0x5817D8) and bit 0x40000 from texture flag 0x100000 (0x581841); bit 0x400000 from texture flags 0x30000, which an MD2 slot's flags 0x10/0x20 set (0x575E9C, 0x581847), and OpenTPW wraps or clamps each slot by it (TextureSlotAddressing). The option [0x785898] is no filter option: by the variables' table position (base 0x785874 + 4 x option index, anchored by the five-valued SKYQUALITY at [0x785888] and the four-valued FIRSTPERSONVIEWDISTANCE at [0x7858B4]) it is the tenth, SPRITESHADOW, and its engine flags 0x20000 (value 0) and 0x40000 (value 1) (0x44DAA0-0x44DAD6) are tested only by the scene pass and the sprite flush (0x576D10, 0x58A7A1, 0x58AA54, 0x58AA5F), never copied into a state word. The preset's filter is TEXTUREFILTERING [0x785878]: 0 and 1 clear and 2 and 3 set bits 0x18 of DAT_008BD550 (0x44D8F0), which the device set-up turns into the device's mip mode and, with bit 0x10 and the caps, an anisotropic MAGFILTER (0x5669CF-0x566A4A). OpenTPW's Veldrid sampler modes stand in for these states ([EXT:texture-filter-samplers]), the per-face bits 0x20000 and 0x40000 are not applied, and a clamped MD2 slot keeps the preset's MINFILTER instead of the original's point MINFILTER.", "the registration that binds option names to the variables at 0x785878.. (the table position is inferred), and which faces carry mesh flag 0x8000000 and texture flag 0x100000" ),
	};

	/// <summary>Logs every approximation once.</summary>
	public static void LogAll( Action<string> warn )
	{
		ArgumentNullException.ThrowIfNull( warn );
		foreach ( var entry in Compatibility )
			warn( $"[APPROX:{entry.Id}] {entry.Area}: {entry.Assumption} Evidence needed: {entry.EvidenceNeeded}." );
	}
}
